package com.ethk3.novaonepro.strategyv2;
import java.io.*;
/** Explicit-duration semi-Markov filter, exact unary permutation emissions and online gradients. */
public final class FamilyF09KernelR26 implements TemporalModelR26,TrainingDiagnosticsR26 {
    private static final int K=3,D=32;private final double[][] logits=new double[K][100],prior=new double[K][D],post=new double[K][D],exit=new double[K][D],stay=new double[K][D];private long t;private TrainingDiagnosticsR26.Step last;
    public FamilyF09KernelR26(){for(int s=0;s<K;s++){prior[s][0]=1.0/K;for(int d=0;d<D;d++){exit[s][d]=1;stay[s][d]=9+s*3;}for(int j=0;j<100;j++)logits[s][j]=.03*Math.sin((s+1)*(j+1));}}
    public void resetTemporalContext(){last=null;for(int s=0;s<K;s++){java.util.Arrays.fill(prior[s],0);java.util.Arrays.fill(post[s],0);prior[s][0]=1.0/K;}}
    public TrainingDiagnosticsR26.Step lastTrainingStep(){return last;}
    public long completedTrainingUpdates(){return t;}
    public String optimizerProtocol(){return "FILTERED_MIXTURE_LOGIT_SGD003_L2_1E_5_CLIP8_AND_DURATION_EXPECTED_COUNTS_V1";}
    public int stateWidth(){return 3;}
    private double hazard(int s,int d){return d==D-1?1:exit[s][d]/(exit[s][d]+stay[s][d]);}
    private ExactPermutationR26.Result[] emissions(){return emissions(logits);}
    private ExactPermutationR26.Result[] emissions(double[][] parameters){ExactPermutationR26.Result[] out=new ExactPermutationR26.Result[K];for(int s=0;s<K;s++){double[][] a=new double[10][10];for(int p=0;p<10;p++)System.arraycopy(parameters[s],p*10,a[p],0,10);out[s]=ExactPermutationR26.infer(a,null);}return out;}
    public void predict(float[][] p,float[] st){ExactPermutationR26.Result[] e=emissions();for(int i=0;i<10;i++)for(int j=0;j<10;j++){double v=0;for(int s=0;s<K;s++)for(int d=0;d<D;d++)v+=prior[s][d]*e[s].marginal[i][j];p[i][j]=(float)v;}double duration=0;for(int s=0;s<K;s++){double v=0;for(int d=0;d<D;d++){v+=prior[s][d];duration+=d*prior[s][d];}st[s]=(float)v;}st[2]=(float)duration;}
    private static double[][] copy(double[][] values){double[][] result=new double[values.length][];for(int i=0;i<values.length;i++)result[i]=values[i].clone();return result;}
    private String inputHash(){StringBuilder b=new StringBuilder("F09_FIXED_CAUSAL_PRIOR_AND_PREVIOUS_POSTERIOR_V1|").append(t);for(double[][] m:new double[][][]{prior,post})for(double[] row:m)for(double x:row)b.append('|').append(Double.toHexString(x));return PolicyIdentityR26.sha256(b.toString());}
    private double mixtureLoss(double[][] parameters,int[] draw){ExactPermutationR26.Result[] e=emissions(parameters);double max=-1e100;double[] ll=new double[K];for(int s=0;s<K;s++){ll[s]=-e[s].logZ;for(int p=0;p<10;p++)ll[s]+=parameters[s][p*10+draw[p]-1];max=Math.max(max,ll[s]);}double z=0;for(int s=0;s<K;s++)for(int d=0;d<D;d++)z+=prior[s][d]*Math.exp(ll[s]-max);if(!(z>0))throw new IllegalStateException("F09_ZERO_MASS");double loss=-max-Math.log(z);for(double[] row:parameters)for(double x:row)loss+=.5e-5*x*x;return loss;}
    public void update(int[] draw){OnlineModelsSU2.requireDraw(draw);ExecutionBudgetR26.poll();if(t==Long.MAX_VALUE)throw new IllegalStateException("F09_UPDATE_CLOCK_CAPACITY");ExactPermutationR26.Result[] e=emissions();double[] ll=new double[K],likelihood=new double[K],gamma=new double[K];double max=-1e100,z=0;for(int s=0;s<K;s++){ll[s]=-e[s].logZ;for(int p=0;p<10;p++)ll[s]+=logits[s][p*10+draw[p]-1];max=Math.max(max,ll[s]);}for(int s=0;s<K;s++){likelihood[s]=Math.exp(ll[s]-max);for(int d=0;d<D;d++)z+=prior[s][d]*likelihood[s];}if(!(z>0))throw new IllegalStateException("F09_ZERO_MASS");double before=-max-Math.log(z),gradientSquared=0,deltaSquared=0;for(double[] row:logits)for(double x:row)before+=.5e-5*x*x;
        double[][] nextLogits=copy(logits),nextExit=copy(exit),nextStay=copy(stay),nextPost=new double[K][D],nextPrior=new double[K][D];
        if(t>0)for(int s=0;s<K;s++)for(int d=0;d<D;d++){double h=hazard(s,d),ex=0,kept=d<D-1?post[s][d]*(1-h)*likelihood[s]/z:0;for(int n=0;n<K;n++)if(n!=s)ex+=post[s][d]*h/(K-1)*likelihood[n]/z;nextExit[s][d]+=ex;nextStay[s][d]+=kept;}
        for(int s=0;s<K;s++)for(int d=0;d<D;d++){nextPost[s][d]=prior[s][d]*likelihood[s]/z;gamma[s]+=nextPost[s][d];}
        for(int s=0;s<K;s++){for(int p=0;p<10;p++)for(int n=0;n<10;n++){int j=p*10+n;double g=gamma[s]*(e[s].marginal[p][n]-(draw[p]==n+1?1:0)),gradient=g+1e-5*logits[s][j];gradientSquared+=gradient*gradient;nextLogits[s][j]=Math.max(-8,Math.min(8,logits[s][j]-.03*(g+1e-5*logits[s][j])));}for(int d=0;d<D;d++){double h=d==D-1?1:nextExit[s][d]/(nextExit[s][d]+nextStay[s][d]);if(d<D-1)nextPrior[s][d+1]+=nextPost[s][d]*(1-h);for(int n=0;n<K;n++)if(n!=s)nextPrior[n][0]+=nextPost[s][d]*h/(K-1);}}
        for(int m=0;m<3;m++){double[][] old=m==0?logits:m==1?exit:stay,updated=m==0?nextLogits:m==1?nextExit:nextStay;for(int s=0;s<K;s++)for(int j=0;j<old[s].length;j++){double change=updated[s][j]-old[s][j];deltaSquared+=change*change;}}
        // Freeze the pre-label filtering prior for both losses. Duration counts are
        // an expected-count update for the next prior, not a claimed SGD gradient.
        TrainingDiagnosticsR26.Step step=new TrainingDiagnosticsR26.Step(t+1,before,mixtureLoss(nextLogits,draw),Math.sqrt(gradientSquared),Math.sqrt(deltaSquared),inputHash(),"FILTERED_EXACT_PERMUTATION_MIXTURE_JOINT_NLL_PLUS_HALF_1E_5_LOGIT_L2;FIXED_PRE_LABEL_PRIOR;GRADIENT=300_EMISSION_LOGITS;DURATION_COUNTS_EXPECTED_UPDATE_FOR_NEXT_PRIOR;DELTA=LOGITS_EXIT_AND_STAY_COUNTS");ExecutionBudgetR26.poll();
        for(int s=0;s<K;s++){System.arraycopy(nextLogits[s],0,logits[s],0,100);System.arraycopy(nextExit[s],0,exit[s],0,D);System.arraycopy(nextStay[s],0,stay[s],0,D);System.arraycopy(nextPost[s],0,post[s],0,D);System.arraycopy(nextPrior[s],0,prior[s],0,D);}t++;last=step;
    }
    public void write(DataOutput o)throws IOException{o.writeInt(0x26090001);o.writeLong(t);for(double[][] m:new double[][][]{logits,prior,post,exit,stay})for(double[] row:m)for(double x:row)o.writeDouble(x);}
    public void read(DataInput in)throws IOException{if(in.readInt()!=0x26090001)throw new IOException("F09_ABI");long clock=in.readLong();if(clock<0)throw new IOException("F09_CURSOR");double[][] restoredLogits=new double[K][100],restoredPrior=new double[K][D],restoredPost=new double[K][D],restoredExit=new double[K][D],restoredStay=new double[K][D];for(double[][] m:new double[][][]{restoredLogits,restoredPrior,restoredPost,restoredExit,restoredStay})for(double[] row:m)for(int j=0;j<row.length;j++){double x=in.readDouble();if(!Double.isFinite(x)||Math.abs(x)>1e12)throw new IOException("F09_STATE");row[j]=x;}double z=0;for(double[] row:restoredPrior)for(double x:row){if(x<0||x>1)throw new IOException("F09_POSTERIOR");z+=x;}if(Math.abs(z-1)>1e-8)throw new IOException("F09_POSTERIOR_MASS");for(int s=0;s<K;s++){System.arraycopy(restoredLogits[s],0,logits[s],0,100);System.arraycopy(restoredPrior[s],0,prior[s],0,D);System.arraycopy(restoredPost[s],0,post[s],0,D);System.arraycopy(restoredExit[s],0,exit[s],0,D);System.arraycopy(restoredStay[s],0,stay[s],0,D);}t=clock;last=null;}
}
